import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Running a document","description":"tuimark run shows a document live in the terminal with no host program - an event strip, an NDJSON event log, fixed mock writes, and reload on save.","frontmatter":{"title":"Running a document","description":"tuimark run shows a document live in the terminal with no host program - an event strip, an NDJSON event log, fixed mock writes, and reload on save.","head":[["link",{"rel":"canonical","href":"https://tuimark.vercel.app/guide/run"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Tuimark"}],["meta",{"property":"og:title","content":"Running a document | Tuimark"}],["meta",{"property":"og:description","content":"tuimark run shows a document live in the terminal with no host program - an event strip, an NDJSON event log, fixed mock writes, and reload on save."}],["meta",{"property":"og:url","content":"https://tuimark.vercel.app/guide/run"}],["meta",{"name":"twitter:title","content":"Running a document | Tuimark"}],["meta",{"name":"twitter:description","content":"tuimark run shows a document live in the terminal with no host program - an event strip, an NDJSON event log, fixed mock writes, and reload on save."}]]},"headers":[],"relativePath":"guide/run.md","filePath":"guide/run.md","lastUpdated":1792235915000}'),o={name:"guide/run.md"};function n(h,e,d,r,l,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="running-a-document" tabindex="-1">Running a document <a class="header-anchor" href="#running-a-document" aria-label="Permalink to &quot;Running a document&quot;">​</a></h1><p><code>tuimark run FILE</code> shows a document live in the terminal and lets you use it, with no Go and no parent program. It is the quickest way to see and try what <a href="/guide/tools"><code>dump</code> and <code>play</code></a> describe: every key, click, focus move, and modal behaves as it will in your app, and every action the document fires is listed on screen instead of going to code you have not written yet.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tuimark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.tui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sample.json</span></span></code></pre></div><p><code>run</code> is a development tool. An application ships with <a href="/guide/go-api"><code>Run()</code> in Go</a> or with a parent program over <a href="/guide/host-protocol"><code>tuimark host</code></a>.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Does</th></tr></thead><tbody><tr><td><code>--data FILE.json</code></td><td>binds the file as the store&#39;s root</td></tr><tr><td><code>--theme dark|light</code></td><td>the host&#39;s theme, as <code>Set(&quot;@theme&quot;, …)</code></td></tr><tr><td><code>--strip</code></td><td>shows the event strip from the start (F12 toggles it)</td></tr><tr><td><code>--events FILE.ndjson</code></td><td>writes one JSON line per host action</td></tr><tr><td><code>--mock FILE.json</code></td><td>fixed store writes for each host action</td></tr></tbody></table><h2 id="the-session" tabindex="-1">The session <a class="header-anchor" href="#the-session" aria-label="Permalink to &quot;The session&quot;">​</a></h2><p>The session is the one <code>Run()</code> gives a Go program: the same keys, focus, mouse, terminal probe, and theme detection, and the same <a href="/guide/tools#environment-variables">environment variables</a>, so <code>TUIMARK_THEME</code> beats <code>--theme</code> here too.</p><ul><li><strong>Host actions.</strong> Every action the document names that is not built in (an <code>on:</code> attribute, a keymap row) is answered by <code>run</code> itself: it applies the action&#39;s mock writes, if any, and records the event in the strip and in <code>--events</code>. Nothing else happens, so a document that expects its host to open a modal or fill a list needs a mock for it, or a real host.</li><li><strong>Built-in actions</strong> behave as under <code>Run()</code>. <code>quit</code>, from a keymap row, an <code>on:</code> attribute, or an unbound <code>ctrl+c</code>, ends the session.</li><li><strong>Errors in the document.</strong> A document with error diagnostics still runs, as under <code>Run()</code>, and the <a href="#the-panel">panel</a> lists them from the first frame.</li><li><strong>Always an exit.</strong> Two <code>ctrl+c</code> within one second end the session, even when the document binds <code>ctrl+c</code> to something else. The first press is handled as usual.</li></ul><p><code>run</code> exits <code>0</code> when the session quits or its input ends, <code>1</code> for an error, and 128 + the signal number when a stop signal (<code>SIGTERM</code>, <code>SIGHUP</code>, <code>SIGINT</code>) ends it.</p><h2 id="the-event-strip" tabindex="-1">The event strip <a class="header-anchor" href="#the-event-strip" aria-label="Permalink to &quot;The event strip&quot;">​</a></h2><p>Press <code>F12</code> to show or hide a strip of the most recent events over the bottom rows of the terminal. It starts hidden, or shown with <code>--strip</code>. On a keyboard where <code>F12</code> is a media key, press <code>fn</code>+<code>F12</code>, or use <code>--strip</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>save list {&quot;row&quot;:&quot;t-2&quot;} null</span></span>
<span class="line"><span>! add_item: tuimark: bad path &quot;items..x&quot;</span></span>
<span class="line"><span>add_item composer {} &quot;buy milk&quot;</span></span>
<span class="line"><span>login password {} [redacted]</span></span>
<span class="line"><span>reload</span></span></code></pre></div><ul><li>An event is <code>ACTION SOURCE KEYS VALUE</code>, the way <code>play</code> prints it: <code>SOURCE</code> is the id of the node that fired it (<code>-</code> for none), <code>KEYS</code> the keys of the list or table row it concerns, and <code>VALUE</code> its value (an input&#39;s text, a tab&#39;s id, …), both as JSON. The value of a <code>secret</code> input&#39;s event is shown as <code>[redacted]</code>.</li><li>A mock batch that failed is <code>! ACTION: ERROR</code>, just before the event&#39;s own line.</li><li><code>! events: ERROR</code> says that writing <code>--events</code> failed (once).</li><li><code>reload</code> marks a successful <a href="#reload">reload</a>.</li></ul><p>The strip shows the last <code>min(8, max(1, floor(rows / 3)))</code> entries, newest last, each cut to the terminal&#39;s width: 8 on a 24-row terminal or taller, fewer on a short one.</p><p>The strip is painted after the frame is built, and is not part of it: the document is laid out at the full terminal size, and no dump, <code>Get</code>, or hit test sees the strip. A click on the strip acts on whatever the frame has under it, as if the strip were hidden.</p><p><code>F12</code> is only for <code>run</code>. It is not a key token, so a document cannot bind it, <code>play</code> has no step for it, and under <code>Run()</code> and <code>tuimark host</code> the key is ignored.</p><h2 id="the-panel" tabindex="-1">The panel <a class="header-anchor" href="#the-panel" aria-label="Permalink to &quot;The panel&quot;">​</a></h2><p>The panel lists the document&#39;s static diagnostics (parse and stylesheet problems), or the error of a failed reload, in <code>validate</code>&#39;s text form, over the top rows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error V002 app.tui:4:11 /screen/text attribute &quot;bogus&quot; is not allowed on &lt;text&gt;</span></span></code></pre></div><p>It shows at most <code>max(1, floor(rows / 3))</code> lines; when there are more, the last one reads <code>… N more</code>. It stays while there is something to list and goes away after a reload that leaves nothing to list. On a short terminal where the panel and the strip overlap, the strip wins.</p><h2 id="events" tabindex="-1">--events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;--events&quot;">​</a></h2><p><code>--events FILE.ndjson</code> appends one line per host action as it fires, with the members of the <a href="/guide/host-protocol">host protocol</a>&#39;s <code>event</code> message, without <code>type</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;seq&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;save&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;list&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;keys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;row&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;t-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;seq&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;login&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;keys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;redacted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>seq</code> counts from 1 in each session.</li><li>An event whose source is a <code>secret</code> input has no <code>value</code>, and ends with <code>&quot;redacted&quot;: true</code>.</li><li>A regular file is created with mode <code>0600</code>, or truncated and set to <code>0600</code>. A pipe or a FIFO is written as it is. A terminal is refused, since <code>run</code> itself owns the terminal: the strip is the place to watch events on screen.</li><li>When a write fails, the log stops and says so once in the strip; the session goes on.</li></ul><h2 id="mock" tabindex="-1">--mock <a class="header-anchor" href="#mock" aria-label="Permalink to &quot;--mock&quot;">​</a></h2><p>A mock lets a prototype react without a backend. The file is one JSON object: each member names an action, and its value is the list of store writes to make when it fires, the <code>writes</code> of a host protocol <code>batch</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;add_item&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;saved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;toggle_help&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;help_open&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>When the action fires, its writes are applied as one <code>Batch</code>, before the event is recorded, so the frame that follows shows them.</li><li>Values are written as they are: nothing in them is read from the event or the store. A mock cannot append to a list, count, or filter. When a prototype needs that, give it a host program: <code>tuimark new NAME --go</code> or <code>--ts</code>.</li><li>A batch that fails changes nothing, adds a <code>! ACTION:</code> line to the strip, and the session goes on.</li><li>A member that names no action of the document, or a built-in action such as <code>quit</code>, is an error, so a typo is caught at once. So is a value that is not a list of writes.</li></ul><h2 id="reload" tabindex="-1">Reload <a class="header-anchor" href="#reload" aria-label="Permalink to &quot;Reload&quot;">​</a></h2><p><code>run</code> watches the document, the stylesheets it loads with <code>&lt;style src&gt;</code>, <code>--data</code>, and <code>--mock</code>, every 150 ms, the way <code>preview --watch</code> does. Save a change and the session picks it up in place, with no restart. Changes seen in one look are one reload.</p><p>A reload succeeds when the document loads with no error diagnostic and the mock is valid for it. The session then goes on with the new document:</p><ul><li><strong>The store</strong> carries over, so whatever the session wrote is still there, unless <code>--data</code> changed: then the new file is the store.</li><li><strong>Kept</strong>, for every node whose <code>id</code> is in the new document with the same tag: the focus and the active screen, list and table cursors, scroll offsets (and a <code>stick=&quot;bottom&quot;</code> scroll&#39;s state), an input&#39;s text and cursor, and the active tab.</li><li><strong>Everything else</strong> starts over. The first frame after a reload compares with the last one before it, so a modal that was open stays open without firing <code>on:open</code> again, and focus that had to move because its node is gone fires <code>on:focus</code> where it lands.</li><li>The strip gets a <code>reload</code> line, and the panel shows the new document&#39;s warnings, or goes away.</li></ul><p>When a reload fails, because the document no longer parses, has an error, or the mock or the data is invalid, the old document runs on unchanged and the panel shows why. Fix the file and the next save reloads it.</p><h2 id="errors-before-the-session" tabindex="-1">Errors before the session <a class="header-anchor" href="#errors-before-the-session" aria-label="Permalink to &quot;Errors before the session&quot;">​</a></h2><p>These print one <code>tuimark: run: …</code> line on stderr and exit <code>1</code> before the terminal is touched:</p><ul><li>no <code>FILE</code>, or more than one;</li><li>a <code>FILE</code>, <code>--data</code>, or <code>--mock</code> that cannot be read, or is not valid JSON;</li><li>a mock that names an unknown or built-in action, or whose values are not lists of <code>{&quot;path&quot;, &quot;value&quot;}</code> writes;</li><li>an <code>--events</code> file that cannot be opened, or that is a terminal;</li><li>a terminal <code>Run()</code> cannot use (for example, when stdin is not a terminal).</li></ul>`,36)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
